class PaginationCycleError(RuntimeError):
    pass

def collect_pages(fetch_page, query):
    items = []
    params = dict(query)
    seen = set()
    initial = params.get("cursor")
    if initial is not None:
        seen.add(initial)
    while True:
        page = fetch_page(dict(params))
        items.extend(page["items"])
        cursor = page.get("next_cursor")
        if cursor is None:
            return items
        if cursor in seen:
            raise PaginationCycleError(cursor)
        seen.add(cursor)
        params["cursor"] = cursor

