import unittest
from pagination import collect_pages
class Regression(unittest.TestCase):
    def test_empty_page_continues(self):
        pages = iter([{"items": [], "next_cursor": "next"}, {"items": [7]}])
        self.assertEqual(collect_pages(lambda _: next(pages), {}), [7])
